/**
 * Skills + categories CRUD actions + Phase A skill levels + designation matrix.
 * @module     local_airpay_skills/skill_actions
 * @copyright  2026 Airpay Payment Services
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define("local_airpay_skills/skill_actions", [
    "core_form/modalform",
    "core/str",
    "core/notification",
    "core/ajax"
], function(ModalForm, Str, Notification, Ajax) {
    "use strict";

    var openSkillForm = function(skillid, returnFocus) {
        var titleKey = (skillid === 0) ? "addskill" : "editskill";
        Str.get_string(titleKey, "local_airpay_skills").then(function(title) {
            var modalForm = new ModalForm({
                formClass: "local_airpay_skills\\form\\edit_skill",
                args: {skillid: skillid},
                modalConfig: {title: title},
                returnFocus: returnFocus
            });
            modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function(event) {
                var message = (event.detail && event.detail.message) || "Saved.";
                Notification.addNotification({message: message, type: "success"});
                window.location.reload();
            });
            modalForm.show();
            return null;
        }).catch(Notification.exception);
    };

    var openCategoryForm = function(categoryid, returnFocus) {
        var titleKey = (categoryid === 0) ? "addcategory" : "editcategory";
        Str.get_string(titleKey, "local_airpay_skills").then(function(title) {
            var modalForm = new ModalForm({
                formClass: "local_airpay_skills\\form\\edit_category",
                args: {categoryid: categoryid},
                modalConfig: {title: title},
                returnFocus: returnFocus
            });
            modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function(event) {
                var message = (event.detail && event.detail.message) || "Saved.";
                Notification.addNotification({message: message, type: "success"});
                window.location.reload();
            });
            modalForm.show();
            return null;
        }).catch(Notification.exception);
    };

    var confirmDelete = function(methodname, args, name, msgKey, titleKey, successKey, returnFocus) {
        Promise.all([
            Str.get_string(titleKey, "local_airpay_skills"),
            Str.get_string(msgKey, "local_airpay_skills", name),
            Str.get_string("delete", "core"),
            Str.get_string(successKey, "local_airpay_skills")
        ]).then(function(strings) {
            Notification.deleteCancelPromise(strings[0], strings[1], strings[2], returnFocus).then(function() {
                Ajax.call([{methodname: methodname, args: args}])[0]
                    .then(function() {
                        Notification.addNotification({message: strings[3], type: "success"});
                        window.location.reload();
                        return null;
                    }).catch(Notification.exception);
                return true;
            }, function() { return null; });
            return null;
        }).catch(Notification.exception);
    };

    // ─── Phase A — skill-level definitions + designation-skill matrix ───

    var openLevelForm = function(skillid, level, returnFocus) {
        var modalForm = new ModalForm({
            formClass: "local_airpay_skills\\form\\edit_skill_level_dynamic_form",
            args: {skillid: skillid, level: level},
            modalConfig: {title: "Edit level " + level},
            returnFocus: returnFocus
        });
        modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function() {
            Notification.addNotification({message: "Level definition saved.", type: "success"});
            window.location.reload();
        });
        modalForm.show();
    };

    var openDesignationSkillForm = function(designation, rowid, returnFocus) {
        var title = rowid === 0
            ? "Add required skill — " + designation
            : "Edit required skill — " + designation;
        var modalForm = new ModalForm({
            formClass: "local_airpay_skills\\form\\edit_designation_skill_dynamic_form",
            args: {designation: designation, rowid: rowid},
            modalConfig: {title: title},
            returnFocus: returnFocus
        });
        modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function() {
            Notification.addNotification({message: "Required skill saved.", type: "success"});
            window.location.reload();
        });
        modalForm.show();
    };

    var confirmDeleteDesignationSkill = function(rowid, skillname, returnFocus) {
        Notification.deleteCancelPromise(
            "Remove required skill",
            "Remove required skill \"" + skillname + "\" from this designation?",
            "Remove", returnFocus).then(function() {
            Ajax.call([{
                methodname: "local_airpay_skills_delete_designation_skill",
                args: {id: rowid}
            }])[0].then(function() {
                Notification.addNotification({message: "Removed.", type: "success"});
                window.location.reload();
                return null;
            }).catch(Notification.exception);
            return true;
        }, function() { return null; });
    };

    var promptCopyDesignation = function(fromDesignation, returnFocus) {
        var target = window.prompt(
            "Copy all required skills from \"" + fromDesignation + "\" to which designation?", "");
        if (!target || target.trim() === "" || target === fromDesignation) {
            if (returnFocus) returnFocus.focus();
            return;
        }
        Ajax.call([{
            methodname: "local_airpay_skills_copy_designation",
            args: {fromdesignation: fromDesignation, todesignation: target.trim()}
        }])[0].then(function(result) {
            Notification.addNotification({
                message: "Copied " + result.copied + " required-skill row(s) to \"" + target.trim() + "\".",
                type: "success"
            });
            var url = new URL(window.location);
            url.searchParams.set("designation", target.trim());
            window.location = url.toString();
            return null;
        }).catch(Notification.exception);
    };

    var wireDesignationSelector = function() {
        var sel = document.getElementById("ap-skills-designation");
        if (!sel) return;
        sel.addEventListener("change", function() {
            var url = new URL(window.location);
            if (sel.value) {
                url.searchParams.set("designation", sel.value);
            } else {
                url.searchParams.delete("designation");
            }
            window.location = url.toString();
        });
    };

    var handleClick = function(event) {
        var trigger = event.target.closest("[data-action]");
        if (!trigger) return;
        var action = trigger.dataset.action;
        var id = parseInt(trigger.dataset.id || "0", 10);
        var name = trigger.dataset.name || "this item";
        var skillid = parseInt(trigger.dataset.skillid || "0", 10);
        var level = parseInt(trigger.dataset.level || "0", 10);
        var designation = trigger.dataset.designation || "";
        var rowid = parseInt(trigger.dataset.rowid || "0", 10);
        switch (action) {
            case "create-skill":    event.preventDefault(); openSkillForm(0, trigger); break;
            case "edit-skill":      event.preventDefault(); openSkillForm(id, trigger); break;
            case "delete-skill":    event.preventDefault();
                confirmDelete("local_airpay_skills_delete_skill", {skillid: id}, name,
                    "confirmdeleteskill", "deleteskill", "skilldeleted", trigger);
                break;
            case "create-category": event.preventDefault(); openCategoryForm(0, trigger); break;
            case "edit-category":   event.preventDefault(); openCategoryForm(id, trigger); break;
            case "delete-category": event.preventDefault();
                confirmDelete("local_airpay_skills_delete_category", {categoryid: id}, name,
                    "confirmdeletecategory", "deletecategory", "categorydeleted", trigger);
                break;
            case "edit-level":                event.preventDefault(); openLevelForm(skillid, level, trigger); break;
            case "add-designation-skill":     event.preventDefault(); openDesignationSkillForm(designation, 0, trigger); break;
            case "edit-designation-skill":    event.preventDefault(); openDesignationSkillForm(designation, rowid, trigger); break;
            case "delete-designation-skill":  event.preventDefault();
                confirmDeleteDesignationSkill(rowid, name || trigger.dataset.skill || "this skill", trigger);
                break;
            case "copy-designation":          event.preventDefault(); promptCopyDesignation(trigger.dataset.from || "", trigger); break;
        }
    };

    return {
        init: function(config) {
            config = config || {};
            if (config.page === "designation_matrix") {
                wireDesignationSelector();
            }
            var root = document.querySelector('[data-region="airpay-skills"]') || document.body;
            if (root.dataset.airpaySkillsInit === "1") return;
            root.dataset.airpaySkillsInit = "1";
            root.addEventListener("click", handleClick);
        }
    };
});
